(() => {
  'use strict';

  const escape = value => String(value ?? '').replace(/[&<>'"]/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;'
  }[character]));

  const optionSets = Object.freeze({
    provinces: ['Eastern Cape', 'Free State', 'Gauteng', 'KwaZulu-Natal', 'Limpopo', 'Mpumalanga', 'North West', 'Northern Cape', 'Western Cape'],
    maritalStatuses: ['Single', 'Married', 'Living with partner', 'Divorced', 'Widowed'],
    employmentStatuses: ['Employed full-time', 'Employed part-time', 'Self-employed', 'Pension', 'Contract / temporary', 'Other regular income'],
    payFrequencies: ['Monthly', 'Twice a month', 'Every two weeks', 'Weekly'],
    accountTypes: ['Cheque / Current', 'Savings', 'Transmission'],
    banks: [
      { value: 'ABSA Bank', branchCode: '632005' },
      { value: 'Capitec Bank', branchCode: '470010' },
      { value: 'First National Bank', branchCode: '250655' },
      { value: 'Nedbank', branchCode: '198765' },
      { value: 'Standard Bank', branchCode: '051001' },
      { value: 'Access Bank', branchCode: '410105' },
      { value: 'African Bank Limited', branchCode: '430000' },
      { value: 'African Bank Incorp', branchCode: '431010' },
      { value: 'Bidvest Bank', branchCode: '462005' },
      { value: 'Discovery Bank', branchCode: '679000' },
      { value: 'Finbond Bank', branchCode: '589000' },
      { value: 'OM Bank Limited', branchCode: '352000' },
      { value: 'TymeBank', branchCode: '678910' }
    ]
  });

  const fieldLabels = Object.freeze({
    first_name: 'First name', last_name: 'Surname', id_number: 'ID number', mobile: 'Mobile number', email: 'Email',
    marital_status: 'Marital status', dependants: 'Dependants', province: 'Province', residential_address: 'Residential address',
    employment_status: 'Income source', income_source_name: 'Employer / income source', job_title: 'Job title / occupation',
    employment_start_month: 'Employment start month', net_monthly_income: 'Net monthly income', pay_frequency: 'Pay frequency',
    pay_day: 'Pay day', housing_expense: 'Rent / bond', food_expense: 'Groceries & household', transport_expense: 'Transport',
    utilities_expense: 'Utilities & communication', insurance_expense: 'Insurance / medical', dependant_expense: 'School / childcare / dependants',
    debt_expense: 'Existing loans / credit repayments', other_expense: 'Other regular expenses', bank_name: 'Bank',
    bank_account_type: 'Account type', bank_account_holder: 'Account holder', bank_account_number: 'Account number', branch_code: 'Branch code'
  });

  const requiredProfileKeys = Object.freeze([
    'first_name', 'last_name', 'id_number', 'mobile', 'marital_status', 'dependants', 'province', 'residential_address',
    'employment_status', 'income_source_name', 'job_title', 'employment_start_month', 'net_monthly_income', 'pay_frequency',
    'housing_expense', 'food_expense', 'transport_expense', 'utilities_expense', 'insurance_expense', 'dependant_expense',
    'debt_expense', 'other_expense', 'bank_name', 'bank_account_type', 'bank_account_holder', 'bank_account_number', 'branch_code'
  ]);

  const numericKeys = new Set([
    'dependants', 'net_monthly_income', 'pay_day', 'housing_expense', 'food_expense', 'transport_expense',
    'utilities_expense', 'insurance_expense', 'dependant_expense', 'debt_expense', 'other_expense'
  ]);

  const bankBranchCode = bankName => optionSets.banks.find(bank => bank.value === bankName)?.branchCode || '';
  const optionValue = option => typeof option === 'string' ? option : option.value;
  const optionLabel = option => typeof option === 'string' ? option : (option.label || option.value);

  function optionHtml(setName, selected = '', placeholder = 'Select') {
    const options = optionSets[setName] || [];
    return [`<option value="">${escape(placeholder)}</option>`, ...options.map(option => {
      const value = optionValue(option);
      const branch = typeof option === 'object' && option.branchCode ? ` data-branch-code="${escape(option.branchCode)}"` : '';
      return `<option value="${escape(value)}"${branch}${value === selected ? ' selected' : ''}>${escape(optionLabel(option))}</option>`;
    })].join('');
  }

  function populateSelect(select, setName, placeholder) {
    if (!select) return;
    const selected = select.value;
    select.innerHTML = optionHtml(setName, selected, placeholder || select.dataset.placeholder || 'Select');
  }

  function populateAll(root = document) {
    root.querySelectorAll('[data-profile-options]').forEach(select => populateSelect(select, select.dataset.profileOptions));
  }

  function validSaId(value) {
    const id = String(value || '').replace(/\D/g, '');
    if (!/^\d{13}$/.test(id)) return false;
    let oddSum = 0;
    for (let index = 0; index < 12; index += 2) oddSum += Number(id[index]);
    const evenDigits = id.slice(1, 12).split('').filter((_, index) => index % 2 === 0).join('');
    const evenSum = [...String(Number(evenDigits) * 2)].reduce((sum, digit) => sum + Number(digit), 0);
    return ((10 - ((oddSum + evenSum) % 10)) % 10) === Number(id[12]);
  }

  const validEmail = value => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value || '').trim());
  const validMobile = value => /^(?:\+27|27|0)\d{9}$/.test(String(value || '').replace(/[\s()-]/g, ''));
  const normalizeMobile = value => {
    const raw = String(value || '').replace(/[\s()-]/g, '');
    if (/^0\d{9}$/.test(raw)) return `+27${raw.slice(1)}`;
    if (/^27\d{9}$/.test(raw)) return `+${raw}`;
    return raw;
  };
  const cleanText = value => String(value ?? '').trim().replace(/\s+/g, ' ');

  function profileFromFormData(formData) {
    const payload = {};
    for (const key of Object.keys(fieldLabels)) {
      if (!formData.has(key)) continue;
      const raw = formData.get(key);
      payload[key] = numericKeys.has(key) ? (raw === '' ? null : Number(raw)) : cleanText(raw);
    }
    if (payload.id_number !== undefined) payload.id_number = String(payload.id_number).replace(/\D/g, '');
    if (payload.mobile !== undefined) payload.mobile = normalizeMobile(payload.mobile);
    if (payload.email !== undefined) payload.email = String(payload.email).trim().toLowerCase();
    if (/^\d{4}-\d{2}$/.test(payload.employment_start_month || '')) payload.employment_start_month += '-01';
    if (payload.bank_name !== undefined) payload.branch_code = bankBranchCode(payload.bank_name);
    return payload;
  }

  function validateProfile(payload, options = {}) {
    const errors = [];
    const required = options.requiredKeys || requiredProfileKeys;
    required.forEach(key => {
      const value = payload[key];
      if (value === null || value === undefined || (typeof value === 'string' && !value.trim())) errors.push(`${fieldLabels[key] || key} is required.`);
    });
    if (payload.id_number && !validSaId(payload.id_number)) errors.push('Enter a valid South African ID number.');
    if (payload.mobile && !validMobile(payload.mobile)) errors.push('Enter a valid South African mobile number.');
    if (payload.email && !validEmail(payload.email)) errors.push('Enter a valid email address.');
    if (payload.dependants !== undefined && (!Number.isInteger(payload.dependants) || payload.dependants < 0 || payload.dependants > 20)) errors.push('Dependants must be between 0 and 20.');
    if (payload.pay_day !== null && payload.pay_day !== undefined && (!Number.isInteger(payload.pay_day) || payload.pay_day < 1 || payload.pay_day > 31)) errors.push('Pay day must be between 1 and 31.');
    for (const key of numericKeys) if (payload[key] !== null && payload[key] !== undefined && (!Number.isFinite(payload[key]) || payload[key] < 0)) errors.push(`${fieldLabels[key] || key} cannot be negative.`);
    if (payload.bank_name && !bankBranchCode(payload.bank_name)) errors.push('Select a bank from the list.');
    if (payload.bank_account_number && !/^\d{6,20}$/.test(String(payload.bank_account_number).replace(/\s/g, ''))) errors.push('Enter a valid bank account number.');
    return [...new Set(errors)];
  }

  window.KredRunClientProfile = Object.freeze({
    optionSets, fieldLabels, requiredProfileKeys, optionHtml, populateSelect, populateAll,
    bankBranchCode, profileFromFormData, validateProfile, validSaId, validEmail, validMobile,
    normalizeMobile, escape
  });

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => populateAll());
  else populateAll();
})();

(() => {
  'use strict';
  if (window.__kredrunCreditBureauConsentLoaded) return;
  window.__kredrunCreditBureauConsentLoaded = true;

  const form = document.querySelector('#loanApplication');
  if (!form) return;
  const client = window.kredrunSupabase;
  const consentBox = form.querySelector('.consent-box');
  if (!client || !consentBox) return;

  const DRAFT_KEY = 'kredrun-application-draft-v2';
  function removeConsentFromDraft() {
    try {
      const raw = localStorage.getItem(DRAFT_KEY);
      if (!raw) return;
      const draft = JSON.parse(raw);
      if (!draft || typeof draft !== 'object' || !Object.prototype.hasOwnProperty.call(draft,'bureauConsent')) return;
      delete draft.bureauConsent;
      localStorage.setItem(DRAFT_KEY, JSON.stringify(draft));
    } catch (_) {}
  }
  removeConsentFromDraft();

  const marketing = form.elements.marketingConsent?.closest('label');
  const row = document.createElement('label');
  row.className = 'check-row';
  row.dataset.bureauConsentRow = '';
  row.innerHTML = '<input type="checkbox" name="bureauConsent" value="yes" required><span>I consent to the lender obtaining and using my credit-bureau information from a registered credit bureau to assess this application, including my credit profile, repayment history and credit score where applicable.</span>';
  if (marketing) consentBox.insertBefore(row, marketing);
  else consentBox.append(row);

  const alertBox = form.querySelector('[data-form-alert]');
  const submitButton = form.querySelector('[data-submit]') || form.querySelector('button[type="submit"]');
  let consentRecordedForSubmission = false;
  let recording = false;

  function showError(message) {
    if (alertBox) {
      alertBox.textContent = message;
      alertBox.className = 'form-alert show error';
      alertBox.scrollIntoView({ behavior:'smooth', block:'nearest' });
    } else {
      window.alert(message);
    }
  }

  // The main application draft serializer sees dynamically added fields. Remove
  // this specific consent again after draft saves so each application requires
  // a fresh, active consent decision by the applicant.
  form.addEventListener('input', () => setTimeout(removeConsentFromDraft, 500));
  form.addEventListener('change', () => setTimeout(removeConsentFromDraft, 500));

  form.addEventListener('submit', async event => {
    if (consentRecordedForSubmission) {
      consentRecordedForSubmission = false;
      removeConsentFromDraft();
      return;
    }
    if (recording) {
      event.preventDefault();
      event.stopImmediatePropagation();
      return;
    }
    const checkbox = form.elements.bureauConsent;
    if (!checkbox?.checked) return;

    event.preventDefault();
    event.stopImmediatePropagation();
    recording = true;
    if (submitButton) submitButton.disabled = true;

    try {
      const { data, error: userError } = await client.auth.getUser();
      if (userError) throw userError;
      const user = data?.user;
      if (!user?.id) throw new Error('Please sign in again before submitting your application.');

      const { error } = await client.from('credit_bureau_consents').insert({
        user_id: user.id,
        consent_version: 'credit-bureau-v1',
        source: 'online_application'
      });
      if (error) throw error;

      consentRecordedForSubmission = true;
      recording = false;
      removeConsentFromDraft();
      if (submitButton) submitButton.disabled = false;
      if (typeof form.requestSubmit === 'function') form.requestSubmit(submitButton || undefined);
      else form.submit();
    } catch (error) {
      recording = false;
      if (submitButton) submitButton.disabled = false;
      showError(error?.message || 'We could not record your credit-bureau consent. Please try again.');
    }
  }, true);
})();

(() => {
  'use strict';

  if (window.__kredrunCustomerUxLoaded) return;
  window.__kredrunCustomerUxLoaded = true;

  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];

  function addStyles() {
    if ($('#kredrun-customer-ux-styles')) return;
    const style = document.createElement('style');
    style.id = 'kredrun-customer-ux-styles';
    style.textContent = `
      .profile-details-section.profile-card{border:1px solid #e1eaf2!important;border-radius:16px;padding:0!important;margin:0 0 12px!important;background:#fff;overflow:hidden}
      .profile-details-section.profile-card+.profile-details-section.profile-card{border-top:1px solid #e1eaf2!important;padding-top:0!important}
      .profile-section-title{width:100%;border:0;background:#fff;color:#183153;padding:17px 18px;display:flex;align-items:center;justify-content:space-between;gap:14px;text-align:left;cursor:pointer;font:inherit}
      .profile-section-title:hover{background:#f8fbfd}
      .profile-section-title:focus-visible{outline:3px solid rgba(28,116,216,.25);outline-offset:-3px}
      .profile-section-title span{display:grid;gap:3px}
      .profile-section-title strong{font-size:.98rem}
      .profile-section-title small{font-size:.76rem;font-weight:600;color:#758397}
      .profile-section-title b{font-size:1.2rem;line-height:1;color:#718096;transition:transform .18s ease}
      .profile-section-title[aria-expanded="true"] b{transform:rotate(180deg)}
      .profile-section-body{padding:0 18px 18px}
      .profile-details-section.profile-card>h3{display:none}
      .portal-next-action{display:block;margin-top:5px;color:#52647a;font-size:.77rem;line-height:1.45;font-weight:600}
      .portal-next-action.is-urgent{color:#b6333d}
      .application-focus-bottom strong{line-height:1.45}
      .customer-optional-note{display:block;margin-top:5px;color:#748397;font-size:.75rem;line-height:1.4}
      @media(max-width:640px){
        .profile-section-title{padding:15px 14px}
        .profile-section-body{padding:0 14px 15px}
      }
      @media(prefers-reduced-motion:reduce){.profile-section-title b{transition:none}}
    `;
    document.head.appendChild(style);
  }

  function makeEmailOptional(root) {
    const email = $('[name="email"]', root);
    if (!email) return;
    email.required = false;
    email.removeAttribute('aria-required');
    const label = root.querySelector(`label[for="${email.id}"]`);
    if (label) label.textContent = 'Email address (optional)';
    const field = email.closest('.field,.auth-field');
    const hint = field?.querySelector('.field-hint,.customer-optional-note');
    if (hint) {
      hint.textContent = 'Optional. Your mobile number can be used for login and account updates.';
      hint.classList.add('customer-optional-note');
    } else if (field) {
      const note = document.createElement('small');
      note.className = 'customer-optional-note';
      note.textContent = 'Optional. Your mobile number can be used for login and account updates.';
      field.append(note);
    }
  }

  function setupProfileSections() {
    const form = $('#profileForm');
    if (!form || form.dataset.uxSectionsReady === 'true') return;
    form.dataset.uxSectionsReady = 'true';
    makeEmailOptional(form);

    const sections = $$('.profile-details-section', form);
    sections.forEach((section, index) => {
      const heading = $('h3', section);
      const grid = $('.profile-grid', section);
      if (!heading || !grid) return;

      section.classList.add('profile-card');
      grid.classList.add('profile-section-body');
      grid.hidden = index !== 0;
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'profile-section-title';
      button.setAttribute('aria-expanded', String(index === 0));
      button.innerHTML = `<span><strong>${heading.textContent}</strong><small>${index === 0 ? 'Review or update these details' : 'Tap to review or update'}</small></span><b aria-hidden="true">⌄</b>`;
      heading.insertAdjacentElement('afterend', button);
      button.addEventListener('click', () => {
        const open = button.getAttribute('aria-expanded') !== 'true';
        button.setAttribute('aria-expanded', String(open));
        grid.hidden = !open;
      });
    });

    form.addEventListener('invalid', event => {
      const section = event.target?.closest?.('.profile-details-section');
      if (!section) return;
      const button = $('.profile-section-title', section);
      const body = $('.profile-section-body', section);
      if (button && body) {
        button.setAttribute('aria-expanded', 'true');
        body.hidden = false;
      }
    }, true);
  }

  const applicationNext = {
    received: 'Next: KredRun will review your affordability and documents.',
    submitted: 'Next: KredRun will review your affordability and documents.',
    pending: 'Next: KredRun will review your affordability and documents.',
    under_review: 'Next: the decision will appear here when the review is complete.',
    reviewing: 'Next: the decision will appear here when the review is complete.',
    needs_information: 'Action needed: open Applications and provide the requested information.',
    documents_requested: 'Action needed: open Applications and provide the requested information.',
    approved: 'Next: review the credit offer and costs before accepting a loan.',
    declined: 'Decision complete. Open Applications to view the outcome.',
    rejected: 'Decision complete. Open Applications to view the outcome.',
    cancelled: 'This application is closed. No further action is needed.'
  };

  const loanNext = {
    active: 'Next: pay your next instalment by the due date.',
    overdue: 'Action needed: make a payment or contact KredRun if you need help.',
    approved: 'Next: wait for the payout status to be confirmed.',
    pending: 'Next: wait for the payout status to be confirmed.',
    disbursing: 'Next: payout is being processed.',
    paid: 'Paid in full. No further payment is due.',
    paid_up: 'Paid in full. No further payment is due.',
    settled: 'Settled. No further payment is due.',
    closed: 'This loan is closed. No further payment is due.',
    written_off: 'Contact KredRun if you need help with this account.'
  };

  function statusKey(badge) {
    const cls = [...(badge?.classList || [])].find(name => name.startsWith('status-') && name !== 'status-badge');
    return cls ? cls.slice(7).toLowerCase() : String(badge?.textContent || '').trim().toLowerCase().replace(/\s+/g, '_');
  }

  function annotatePortalRows() {
    $$('.portal-row').forEach(row => {
      if (row.querySelector('.portal-next-action')) return;
      const badge = $('.status-badge', row);
      const key = statusKey(badge);
      const map = row.classList.contains('loan-row') ? loanNext : applicationNext;
      const copy = map[key];
      if (!copy) return;
      const host = row.firstElementChild;
      if (!host) return;
      const note = document.createElement('small');
      note.className = `portal-next-action${key === 'overdue' || key === 'needs_information' || key === 'documents_requested' ? ' is-urgent' : ''}`;
      note.textContent = copy;
      host.append(note);
    });
  }

  function improveCurrentApplication() {
    const panel = $('[data-current-application]');
    const next = panel?.querySelector('[data-current-application-next]');
    if (!panel || !next) return;
    const key = String(panel.dataset.status || '').toLowerCase();
    const copy = applicationNext[key];
    if (copy && next.textContent !== copy) next.textContent = copy;
  }

  function improveLoanDetail() {
    const detail = $('[data-loan-detail-content]');
    if (!detail || detail.querySelector('[data-loan-next-action]')) return;
    const badge = $('.status-badge', detail);
    const key = statusKey(badge);
    const copy = loanNext[key];
    if (!copy) return;
    const head = $('.loan-detail-head', detail);
    if (!head) return;
    const note = document.createElement('p');
    note.dataset.loanNextAction = '';
    note.className = `portal-next-action${key === 'overdue' ? ' is-urgent' : ''}`;
    note.textContent = copy;
    head.insertAdjacentElement('afterend', note);
  }

  function observeAccount() {
    const account = $('.account-shell');
    if (!account) return;
    const refresh = () => {
      annotatePortalRows();
      improveCurrentApplication();
      improveLoanDetail();
    };
    refresh();
    const observer = new MutationObserver(refresh);
    observer.observe(account, { childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'data-status'] });
  }

  function setupApplication() {
    const form = $('#loanApplication');
    if (!form) return;
    makeEmailOptional(form);
  }

  addStyles();
  setupApplication();
  setupProfileSections();
  observeAccount();
})();

(() => {
  const root = document.querySelector('[data-login-identity-auth]');
  if (!root) return;

  // Pin the SDK so a future CDN release cannot unexpectedly change the login page.
  const REMOTE_SOURCES = [
    'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.113.0/dist/umd/supabase.js',
    'https://unpkg.com/@supabase/supabase-js@2.113.0/dist/umd/supabase.js'
  ];
  const isSdkReady = () => typeof window.supabase?.createClient === 'function';
  let pendingId = root.querySelector('input[name="idNumber"]')?.value || '';

  const renderWaiting = (message, failed = false) => {
    const currentId = root.querySelector('input[name="idNumber"]')?.value;
    if (currentId != null) pendingId = currentId;

    root.innerHTML = `
      <form class="login-waiting-form" data-login-waiting-form>
        <div class="auth-field">
          <label>South African ID number</label>
          <input name="idNumber" inputmode="numeric" autocomplete="off" maxlength="13" pattern="[0-9]{13}" placeholder="13 digits" required autofocus>
        </div>
        <button class="btn btn-primary btn-wide" type="submit" disabled aria-disabled="true">${failed ? 'Login unavailable' : 'Getting login ready…'}</button>
      </form>
      ${failed
        ? `<div class="auth-feedback show error" role="alert">${message}<br><button class="auth-link" type="button" data-login-retry>Retry</button></div>`
        : `<div class="login-boot-state" role="status" aria-live="polite"><span class="login-boot-dot" aria-hidden="true"></span><span>${message}</span></div>`}
    `;

    const input = root.querySelector('input[name="idNumber"]');
    if (input) {
      input.value = pendingId;
      input.addEventListener('input', () => { pendingId = input.value; });
    }
    root.querySelector('[data-login-waiting-form]')?.addEventListener('submit', event => event.preventDefault());
    root.querySelector('[data-login-retry]')?.addEventListener('click', start);
  };

  const loadScript = (src, timeout = 18000) => new Promise((resolve, reject) => {
    const script = document.createElement('script');
    let settled = false;
    const finish = (ok, error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      script.onload = script.onerror = null;
      if (!ok) script.remove();
      ok ? resolve() : reject(error || new Error(`Could not load ${src}`));
    };
    const timer = window.setTimeout(() => finish(false, new Error(`Timed out loading ${src}`)), timeout);
    script.src = src;
    script.async = true;
    script.crossOrigin = 'anonymous';
    script.onload = () => finish(isSdkReady(), new Error(`Invalid Supabase SDK from ${src}`));
    script.onerror = () => finish(false, new Error(`Could not load ${src}`));
    document.head.appendChild(script);
  });

  const loadLocal = (src, timeout = 12000) => new Promise((resolve, reject) => {
    if (document.querySelector(`script[data-login-loaded="${src}"]`)) return resolve();
    const script = document.createElement('script');
    let settled = false;
    const finish = (ok, error) => {
      if (settled) return;
      settled = true;
      window.clearTimeout(timer);
      script.onload = script.onerror = null;
      delete script.dataset.loginPending;
      if (!ok) script.remove();
      else script.dataset.loginLoaded = src;
      ok ? resolve() : reject(error || new Error(`Could not load ${src}`));
    };
    const timer = window.setTimeout(() => finish(false, new Error(`Timed out loading ${src}`)), timeout);
    script.src = src;
    script.async = false;
    script.dataset.loginPending = src;
    script.onload = () => finish(true);
    script.onerror = () => finish(false, new Error(`Could not load ${src}`));
    document.body.appendChild(script);
  });

  const resetIncompleteLocalScripts = () => {
    if (window.kredrunSupabase && window.KredRunAuth) return;
    document.querySelectorAll('script[data-login-loaded]').forEach(script => script.remove());
  };

  let running = false;
  async function start() {
    if (running) return;
    running = true;
    renderWaiting('Securing your login…');

    try {
      if (!isSdkReady()) {
        for (const source of REMOTE_SOURCES) {
          try {
            await loadScript(source);
            if (isSdkReady()) break;
          } catch (_) {}
        }
      }
      if (!isSdkReady()) throw new Error('Supabase client unavailable');

      resetIncompleteLocalScripts();
      await loadLocal('assets/js/auth-client.js?v=20260902-1');
      if (!window.kredrunSupabase || !window.KredRunAuth) throw new Error('Authentication client did not initialise');

