            collectionDate: previous.collectionDate,
            days: incoming.days ?? previous.days,
            estimatedTotal: incoming.estimatedTotal ?? previous.estimatedTotal,
          });
        }
      } catch (_) {}
    }
    return originalSetItem.call(this, key, rawValue);
  };

